// @luvallplay/ui: design tokens.
// - Semantic theme tokens (./semantic.ts): the only names components use.
//   The 12 club colour schemes fill them; Court Green (Luvallplay's own) is
//   the default. tokens.css is the default theme, generated by defaultThemeCss().
//   system.css is the design system built on them: derived tokens (the
//   optional EXTRA_TOKENS), type, radii, elevation and motion.
// - luvallplay: the brand's own palette, type, spacing and radii (source data).
// - threeWolves: the club's current look, exactly as globals.css renders it.
//   It becomes Three Wolves' imported brand (§6.3.2) with the theming work.

import { DEFAULT_SCHEME, schemeTheme, themeCss } from "./semantic.ts";

export { luvallplay, type BrandColor, type BrandTheme } from "./luvallplay.ts";
export { threeWolves, threeWolvesCssVars, threeWolvesTheme } from "./three-wolves.ts";
export { FILL_CONTRAST, TEXT_CONTRAST, adjustForContrast, brandFromHtml, brandPasses, contrastRatio, importBrand, parseColor, readableOn, type BrandAdjustment, type BrandColors, type ImportedBrand, type WebsiteBrand } from "./brand.ts";
export { resolveClubTheme, type ClubFont, type ResolvedClubTheme } from "./club-theme.ts";
export {
  COLOR_SCHEMES,
  DEFAULT_SCHEME,
  EXTRA_TOKENS,
  SEMANTIC_TOKENS,
  schemeTheme,
  themeCss,
  type ColorScheme,
  type ExtraToken,
  type ThemeExtras,
  type Mode,
  type SemanticToken,
  type Theme,
} from "./semantic.ts";

/** packages/ui/src/tokens.css: the default theme (Court Green) as semantic custom properties. */
export function defaultThemeCss(): string {
  return [
    "/* Luvallplay default theme (Court Green): semantic tokens, generated by defaultThemeCss() in packages/ui. Don't edit by hand. */",
    themeCss(schemeTheme(DEFAULT_SCHEME, "light"), schemeTheme(DEFAULT_SCHEME, "dark")),
  ].join("\n");
}
